catalog_script_client.script:
function onSubmit() {
    var VariableName = 'contract_type';
    var actionName = g_form.getActionName();
    // check if contract type is active.
    if (g_scratchpad.isCntTypeActive)
        return true;
    g_form.getReference(VariableName, function(cntTypeGr) {
        if (cntTypeGr.active == 'false') {
			var contractName = String(cntTypeGr.name);
			g_form.addErrorMessage(getMessage('The contract type, {0} is inactive. Please contact your system administrator.').replace('{0}',contractName));
            return false;
        }
		g_scratchpad.isCntTypeActive=true;
        g_form.submit(actionName);
    });
    return false;
}
